<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ブロック崩し</title>
<style>
  :root {
    --bg: #0f1220;
    --panel: #171c30;
    --accent: #4fc3f7;
    --text: #e8ecf5;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: "Segoe UI", "Hiragino Sans", "Noto Sans JP", sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
    padding: 16px;
  }
  h1 {
    font-size: 22px;
    letter-spacing: 2px;
    margin-bottom: 10px;
    color: var(--accent);
  }
  #hud {
    display: flex;
    gap: 24px;
    margin-bottom: 10px;
    font-size: 15px;
  }
  #hud span b { color: var(--accent); }
  #wrap { position: relative; }
  canvas {
    background: #0a0d18;
    border: 2px solid #2a3352;
    border-radius: 8px;
    display: block;
    cursor: none;
  }
  #overlay {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 14px;
    background: rgba(10, 13, 24, 0.82);
    border-radius: 8px;
    text-align: center;
    padding: 20px;
  }
  #overlay.hidden { display: none; }
  #overlay h2 { font-size: 28px; }
  #overlay p { font-size: 14px; color: #aab3c8; line-height: 1.7; }
  button {
    background: var(--accent);
    color: #08101f;
    border: none;
    border-radius: 6px;
    padding: 10px 26px;
    font-size: 16px;
    font-weight: 700;
    cursor: pointer;
  }
  button:hover { filter: brightness(1.15); }
  #help { margin-top: 10px; font-size: 12px; color: #8b94ab; }
</style>
</head>
<body>
<h1>ブロック崩し</h1>
<div id="hud">
  <span>スコア <b id="score">0</b></span>
  <span>レベル <b id="level">1</b></span>
  <span>残機 <b id="lives">3</b></span>
  <span>ハイスコア <b id="hiscore">0</b></span>
</div>
<div id="wrap">
  <canvas id="game" width="640" height="480"></canvas>
  <div id="overlay">
    <h2 id="ov-title">ブロック崩し</h2>
    <p id="ov-text">マウスまたは ← → キーでパドルを操作<br>クリック / スペースでボールを発射<br>P キーでポーズ</p>
    <button id="ov-btn">スタート</button>
  </div>
</div>
<div id="help">操作: マウス / ←→キー ・ 発射: クリック or スペース ・ ポーズ: P</div>

<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  const scoreEl = document.getElementById('score');
  const levelEl = document.getElementById('level');
  const livesEl = document.getElementById('lives');
  const hiscoreEl = document.getElementById('hiscore');
  const overlay = document.getElementById('overlay');
  const ovTitle = document.getElementById('ov-title');
  const ovText = document.getElementById('ov-text');
  const ovBtn = document.getElementById('ov-btn');

  const ROW_COLORS = ['#ef5350', '#ff9800', '#ffee58', '#66bb6a', '#42a5f5', '#ab47bc'];

  let hiscore = 0;
  try { hiscore = Number(localStorage.getItem('breakout_hiscore')) || 0; } catch (e) {}
  hiscoreEl.textContent = hiscore;

  // ---- 状態 ----
  let state = 'ready'; // ready | playing | paused | gameover | win
  let score = 0, level = 1, lives = 3;
  let paddle, ball, blocks, particles, powerups;
  let keys = {};

  function newPaddle() {
    return { w: 90, h: 12, x: W / 2 - 45, y: H - 30, speed: 480 };
  }

  function newBall(stuck = true) {
    return {
      x: W / 2, y: H - 45, r: 7,
      vx: 0, vy: 0,
      stuck,
      speed: 260 + (level - 1) * 25
    };
  }

  function buildBlocks() {
    const rows = Math.min(4 + level, 8);
    const cols = 10;
    const bw = 54, bh = 20, gap = 6;
    const offX = (W - (cols * (bw + gap) - gap)) / 2;
    const offY = 50;
    const arr = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        // レベルに応じて一部ブロックを頑丈にする
        const tough = level >= 2 && (r + c) % 7 === 0;
        arr.push({
          x: offX + c * (bw + gap),
          y: offY + r * (bh + gap),
          w: bw, h: bh,
          color: ROW_COLORS[r % ROW_COLORS.length],
          hp: tough ? 2 : 1,
          points: (rows - r) * 10
        });
      }
    }
    return arr;
  }

  function resetLevel(keepScore = true) {
    paddle = newPaddle();
    ball = newBall(true);
    blocks = buildBlocks();
    powerups = [];
    particles = [];
    if (!keepScore) { score = 0; lives = 3; }
    updateHud();
  }

  function updateHud() {
    scoreEl.textContent = score;
    levelEl.textContent = level;
    livesEl.textContent = lives;
    hiscoreEl.textContent = hiscore;
  }

  function launchBall() {
    if (!ball.stuck) return;
    ball.stuck = false;
    const angle = (-Math.PI / 2) + (Math.random() * 0.6 - 0.3);
    ball.vx = Math.cos(angle) * ball.speed;
    ball.vy = Math.sin(angle) * ball.speed;
  }

  function showOverlay(title, text, btnLabel) {
    ovTitle.textContent = title;
    ovText.innerHTML = text;
    ovBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
  }
  function hideOverlay() { overlay.classList.add('hidden'); }

  // ---- パワーアップ ----
  const POWER_TYPES = [
    { kind: 'wide', label: 'W', color: '#4fc3f7' },
    { kind: 'life', label: '+', color: '#66bb6a' },
    { kind: 'slow', label: 'S', color: '#ffee58' }
  ];

  function maybeDropPowerup(x, y) {
    if (Math.random() < 0.12) {
      const t = POWER_TYPES[Math.floor(Math.random() * POWER_TYPES.length)];
      powerups.push({ x, y, vy: 130, ...t });
    }
  }

  function applyPowerup(p) {
    if (p.kind === 'wide') {
      paddle.w = Math.min(150, paddle.w + 25);
    } else if (p.kind === 'life') {
      lives = Math.min(9, lives + 1);
    } else if (p.kind === 'slow') {
      const f = 0.8;
      ball.vx *= f; ball.vy *= f;
    }
    spawnParticles(p.x, p.y, p.color, 12);
  }

  function spawnParticles(x, y, color, n) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = 60 + Math.random() * 140;
      particles.push({
        x, y,
        vx: Math.cos(a) * s, vy: Math.sin(a) * s,
        life: 0.5 + Math.random() * 0.3,
        color
      });
    }
  }

  // ---- 入力 ----
  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    const mx = (e.clientX - rect.left) * (W / rect.width);
    paddle.x = Math.min(W - paddle.w, Math.max(0, mx - paddle.w / 2));
  });
  canvas.addEventListener('mousedown', () => {
    if (state === 'playing') launchBall();
  });
  window.addEventListener('keydown', e => {
    keys[e.key] = true;
    if (e.key === ' ' || e.code === 'Space') {
      e.preventDefault();
      if (state === 'playing') launchBall();
    }
    if (e.key === 'p' || e.key === 'P') {
      if (state === 'playing') { state = 'paused'; showOverlay('ポーズ', 'Pキーで再開', '再開'); }
      else if (state === 'paused') { state = 'playing'; hideOverlay(); }
    }
  });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  ovBtn.addEventListener('click', () => {
    if (state === 'ready' || state === 'gameover' || state === 'win') {
      level = 1;
      resetLevel(false);
      state = 'playing';
      hideOverlay();
    } else if (state === 'paused') {
      state = 'playing';
      hideOverlay();
    }
  });

  // ---- 更新 ----
  function update(dt) {
    // パドル（キー操作）
    if (keys['ArrowLeft'] || keys['a']) paddle.x -= paddle.speed * dt;
    if (keys['ArrowRight'] || keys['d']) paddle.x += paddle.speed * dt;
    paddle.x = Math.min(W - paddle.w, Math.max(0, paddle.x));

    // ボール
    if (ball.stuck) {
      ball.x = paddle.x + paddle.w / 2;
      ball.y = paddle.y - ball.r - 2;
    } else {
      ball.x += ball.vx * dt;
      ball.y += ball.vy * dt;

      // 壁
      if (ball.x - ball.r < 0) { ball.x = ball.r; ball.vx = Math.abs(ball.vx); }
      if (ball.x + ball.r > W) { ball.x = W - ball.r; ball.vx = -Math.abs(ball.vx); }
      if (ball.y - ball.r < 0) { ball.y = ball.r; ball.vy = Math.abs(ball.vy); }

      // 落下
      if (ball.y - ball.r > H) {
        lives--;
        updateHud();
        if (lives <= 0) {
          state = 'gameover';
          if (score > hiscore) {
            hiscore = score;
            try { localStorage.setItem('breakout_hiscore', hiscore); } catch (e) {}
          }
          updateHud();
          showOverlay('ゲームオーバー', `スコア: ${score}<br>ハイスコア: ${hiscore}`, 'もう一度');
        } else {
          ball = newBall(true);
          paddle = newPaddle();
        }
        return;
      }

      // パドル衝突（当たる位置で反射角が変わる）
      if (ball.vy > 0 &&
          ball.y + ball.r >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h &&
          ball.x >= paddle.x - ball.r && ball.x <= paddle.x + paddle.w + ball.r) {
        const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2); // -1..1
        const angle = -Math.PI / 2 + hit * (Math.PI / 3); // 最大60度
        const sp = Math.hypot(ball.vx, ball.vy);
        ball.vx = Math.cos(angle) * sp;
        ball.vy = Math.sin(angle) * sp;
        ball.y = paddle.y - ball.r - 1;
      }

      // ブロック衝突
      for (const b of blocks) {
        if (b.hp <= 0) continue;
        const nx = Math.max(b.x, Math.min(ball.x, b.x + b.w));
        const ny = Math.max(b.y, Math.min(ball.y, b.y + b.h));
        const dx = ball.x - nx, dy = ball.y - ny;
        if (dx * dx + dy * dy <= ball.r * ball.r) {
          // どの面から当たったかで反射方向を決める
          const overlapX = ball.r - Math.abs(dx);
          const overlapY = ball.r - Math.abs(dy);
          if (overlapX < overlapY) {
            ball.vx = dx > 0 ? Math.abs(ball.vx) : -Math.abs(ball.vx);
          } else {
            ball.vy = dy > 0 ? Math.abs(ball.vy) : -Math.abs(ball.vy);
          }
          b.hp--;
          if (b.hp <= 0) {
            score += b.points;
            spawnParticles(b.x + b.w / 2, b.y + b.h / 2, b.color, 14);
            maybeDropPowerup(b.x + b.w / 2, b.y + b.h / 2);
          } else {
            spawnParticles(b.x + b.w / 2, b.y + b.h / 2, b.color, 5);
          }
          updateHud();
          break; // 1フレームに1ブロック
        }
      }

      // 面取り: 速度が極端に水平/垂直にならないよう補正
      const sp = Math.hypot(ball.vx, ball.vy);
      if (sp > 0) {
        const minRatio = 0.25;
        if (Math.abs(ball.vy) < sp * minRatio) {
          ball.vy = Math.sign(ball.vy || -1) * sp * minRatio;
          ball.vx = Math.sign(ball.vx) * Math.sqrt(sp * sp - ball.vy * ball.vy);
        }
        if (Math.abs(ball.vx) < sp * minRatio) {
          ball.vx = Math.sign(ball.vx || 1) * sp * minRatio;
          ball.vy = Math.sign(ball.vy) * Math.sqrt(sp * sp - ball.vx * ball.vx);
        }
      }
    }

    // パワーアップ
    for (const p of powerups) {
      p.y += p.vy * dt;
      if (p.y >= paddle.y && p.y <= paddle.y + paddle.h + 8 &&
          p.x >= paddle.x && p.x <= paddle.x + paddle.w) {
        applyPowerup(p);
        p.dead = true;
      }
      if (p.y > H + 20) p.dead = true;
    }
    powerups = powerups.filter(p => !p.dead);

    // パーティクル
    for (const pt of particles) {
      pt.x += pt.vx * dt;
      pt.y += pt.vy * dt;
      pt.vy += 300 * dt;
      pt.life -= dt;
    }
    particles = particles.filter(pt => pt.life > 0);

    // レベルクリア
    if (blocks.every(b => b.hp <= 0)) {
      level++;
      updateHud();
      resetLevel(true);
      showOverlay(`レベル ${level - 1} クリア!`, '次のレベルへ', '続ける');
      state = 'ready';
      // 「続ける」で再開できるように overlay ボタンを扱う
      ovBtn.onclick = () => {
        state = 'playing';
        hideOverlay();
        ovBtn.onclick = defaultBtnHandler;
      };
    }
  }

  function defaultBtnHandler() {
    if (state === 'ready' || state === 'gameover' || state === 'win') {
      level = 1;
      resetLevel(false);
      state = 'playing';
      hideOverlay();
    } else if (state === 'paused') {
      state = 'playing';
      hideOverlay();
    }
  }
  ovBtn.onclick = defaultBtnHandler;

  // ---- 描画 ----
  function draw() {
    ctx.clearRect(0, 0, W, H);

    // ブロック
    for (const b of blocks) {
      if (b.hp <= 0) continue;
      ctx.fillStyle = b.color;
      ctx.globalAlpha = b.hp >= 2 ? 1 : 0.9;
      roundRect(b.x, b.y, b.w, b.h, 4);
      if (b.hp >= 2) {
        ctx.strokeStyle = 'rgba(255,255,255,0.7)';
        ctx.lineWidth = 2;
        roundRectStroke(b.x + 3, b.y + 3, b.w - 6, b.h - 6, 3);
      }
      ctx.globalAlpha = 1;
    }

    // パドル
    const grad = ctx.createLinearGradient(paddle.x, paddle.y, paddle.x, paddle.y + paddle.h);
    grad.addColorStop(0, '#81d4fa');
    grad.addColorStop(1, '#0288d1');
    ctx.fillStyle = grad;
    roundRect(paddle.x, paddle.y, paddle.w, paddle.h, 6);

    // ボール
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
    ctx.fill();
    if (ball.stuck) {
      ctx.fillStyle = 'rgba(255,255,255,0.5)';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('クリック / スペースで発射', W / 2, paddle.y - 24);
    }

    // パワーアップ
    for (const p of powerups) {
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 10, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#08101f';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(p.label, p.x, p.y + 1);
    }

    // パーティクル
    for (const pt of particles) {
      ctx.globalAlpha = Math.max(0, pt.life * 2);
      ctx.fillStyle = pt.color;
      ctx.fillRect(pt.x - 2, pt.y - 2, 4, 4);
    }
    ctx.globalAlpha = 1;
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
  }
  function roundRectStroke(x, y, w, h, r) {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.stroke();
  }

  // ---- メインループ ----
  let last = performance.now();
  function loop(now) {
    const dt = Math.min(0.033, (now - last) / 1000);
    last = now;
    if (state === 'playing') update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  resetLevel(false);
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
